from pathlib import Path
import sys, json
repo=Path('/home/drx/MIPStarRE-qpbt')
root=Path(sys.argv[1]).resolve()
sys.path.insert(0,str(repo/'scripts'))
from blueprint_lean_sync import collect_file_lean_decls,strip_lean_comments_preserve_lines
from check_source_statement_changes import _header_from_lines
baseline=json.loads(Path('/tmp/qpbt-pr736-native-checkpoint-public-headers-1001.json').read_text())
headers={};ambiguous=[]
for path in sorted((root/'MIPStarRE/QPBT').rglob('*.lean')):
 text=path.read_text();lines=strip_lean_comments_preserve_lines(text)
 for decl in collect_file_lean_decls(path,root/'MIPStarRE',text=text):
  h=_header_from_lines(lines,decl.line)
  if 'private ' in h.split(decl.kind,1)[0]:continue
  if decl.fqn in headers and headers[decl.fqn]['header']!=h:ambiguous.append(decl.fqn)
  headers[decl.fqn]={'file':str(path.relative_to(root)),'line':decl.line,'kind':decl.kind,'header':h}
missing=[];changed=[]
for name,old in baseline['headers'].items():
 new=headers.get(name)
 if new is None:missing.append(name)
 elif new['header']!=old['header']:changed.append({'name':name,'old':old,'new':new})
result={'base':baseline['base'],'root':str(root),'baseline_count':len(baseline['headers']),'current_count':len(headers),'missing':missing,'changed':changed,'ambiguous':ambiguous,'limitation':baseline['scope']}
print(json.dumps(result,indent=2,ensure_ascii=False))
raise SystemExit(1 if missing or changed or ambiguous else 0)

